"""Offline ADB and length-prefixed plist exchange adapters."""
import base64
import io
import plistlib
import struct
from xml.parsers.expat import ExpatError

CNXN = 0x4e584e43
AUTH = 0x48545541
CLSE = 0x45534c43


def checksum(data):
    total = 0
    for byte in data:
        total = (total + byte) & 0xffffffff
    return total


def adb_packet(command, arg0, arg1, body):
    body = bytes(body)
    return struct.pack('<6I', command, arg0, arg1, len(body),
                       checksum(body), command ^ 0xffffffff) + body


def send_connect():
    identity = b'host::zgrab2'
    return adb_packet(CNXN, 0x01000000, 4096, identity)


def send_close():
    return adb_packet(CLSE, 0, 0, b'')


def read_adb_response(data):
    if len(data) < 24:
        raise ValueError('short ADB header')
    command, arg0, arg1, length, check, magic = struct.unpack('<6I', data[:24])
    if command ^ magic != 0xffffffff:
        raise ValueError('bad ADB header')
    if length > 65535:
        raise ValueError('ADB body too long')
    if len(data) != 24 + length:
        raise ValueError('ADB trailing bytes or short body')
    body = data[24:]
    if checksum(body) != check:
        raise ValueError('bad ADB checksum')
    if command == CNXN:
        banner = body.decode('utf-8')
        version = f'{(arg0 >> 16) & 255}.{(arg0 >> 8) & 255}.{arg0 & 255}'
        return ('CNXN', version, banner)
    if command == AUTH:
        return ('AUTH', arg0, arg1, body)
    raise ValueError('unsupported ADB command')


GET_VERSION = 0
GET_PRODUCT_NAME = 1
USBMUXD_COMMANDS = {
    GET_VERSION: ('ProductVersion', 'GetValue'),
    GET_PRODUCT_NAME: ('ProductName', 'GetValue'),
}


def get_value_request(kind):
    key, request = USBMUXD_COMMANDS[kind]
    value = plistlib.dumps({'Key': key, 'Label': 'usbmuxd',
                            'ProtocolVersion': '2', 'Request': request},
                           fmt=plistlib.FMT_XML, sort_keys=False)
    return struct.pack('>I', len(value)) + value


def _read_plist_value(stream, expected_key):
    header = stream.read(4)
    if len(header) != 4:
        raise ValueError('truncated plist length')
    size = struct.unpack('>I', header)[0]
    if size < 1 or size > 65532:
        raise ValueError('invalid plist length')
    body = stream.read(size)
    if len(body) != size:
        raise ValueError('truncated plist body')
    value = plistlib.loads(body)
    if (type(value) is not dict
            or set(value) != {'Key', 'Request', 'Value'}
            or value['Key'] != expected_key
            or value['Request'] != 'GetValue'
            or type(value['Value']) is not str
            or not value['Value']):
        raise ValueError('invalid GetValue response')
    return value['Value']


def send_messages(data):
    stream = io.BytesIO(data)
    version = _read_plist_value(stream, 'ProductVersion')
    product = _read_plist_value(stream, 'ProductName')
    if stream.read(1):
        raise ValueError('trailing plist frame')
    return ('sync', version, product)


def signature(kind, data):
    """Return the parsed open signature, or None for malformed wire data."""
    try:
        if kind == 'tcp':
            if data:
                raise ValueError('TCP payload must be empty')
            return ('tcp',)
        if kind == 'adb':
            return read_adb_response(data)
        if kind == 'sync':
            return send_messages(data)
        return None
    except (ValueError, UnicodeError, OverflowError, TypeError,
            plistlib.InvalidFileException, ExpatError, RecursionError):
        return None


def probe_script(kind):
    encode = lambda b: base64.b64encode(b).decode('ascii')
    if kind == 'tcp':
        return [], []
    if kind == 'adb':
        return [encode(send_connect())], [encode(send_close())]
    if kind == 'sync':
        return ([encode(get_value_request(GET_VERSION)),
                 encode(get_value_request(GET_PRODUCT_NAME))], [])
    raise ValueError('unknown service kind')
PY
